import numpy as np

# Functions for defining noise variance in MR readouts. All functions should return
# a complex array containing real and imaginary noise values with same dimensionality
# as Exp.cReadout as generated by Exp.Acquire()
#
# As inputs, each function accepts a tuple named noiseParams for user control of 
# noise behaviour, the signal noise will be added to, and 8 variables calculated 
# automatically within Experiment() from given sample and magnet parameters.
#
# Original version of this code designed and written by John Adams (jadam33@uwo.ca)
